begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();test_endpoint text:='https://fcm.googleapis.com/fcm/send/'||gen_random_uuid();
 job jsonb;events jsonb;value jsonb;sid uuid;
begin
 insert into auth.users(id,email,raw_user_meta_data) values(a,a||'@example.invalid','{}'),(b,b||'@example.invalid','{}');
 update public.sb_account_access set status='approved' where user_id in(a,b);
 insert into soundbar_private.sb_admins(user_id) values(a);
 perform public.sb_webpush_server('init',jsonb_build_object('publicKey',repeat('A',87),'privateKey',repeat('A',43)));
 perform set_config('request.jwt.claim.sub',b::text,true);execute 'set local role authenticated';
 begin perform public.sb_admin_notifications('config');raise exception 'Nonadmin allowed';exception when insufficient_privilege then null;end;
 begin perform public.sb_webpush_server('config');raise exception 'Secret exposed';exception when insufficient_privilege then null;end;
 if has_table_privilege('authenticated','soundbar_private.sb_push_config','select') then raise exception 'Config table exposed';end if;
 if has_function_privilege('anon','public.sb_admin_notifications(text,jsonb)','execute') then raise exception 'Anonymous API access';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 value:=public.sb_admin_notifications('config');if value ? 'privateKey' or value ? 'dispatchSecret' then raise exception 'Secret in admin config';end if;
 begin perform public.sb_admin_notifications('subscribe',jsonb_build_object('endpoint','https://127.0.0.1/private','p256dh',repeat('A',87),'auth',repeat('A',22)));raise exception 'Unsafe endpoint accepted';exception when raise_exception then if sqlerrm='Unsafe endpoint accepted' then raise;end if;end;
 perform public.sb_admin_notifications('subscribe',jsonb_build_object('endpoint',test_endpoint,'p256dh',repeat('A',87),'auth',repeat('A',22)));
 value:=public.sb_admin_notifications('config',jsonb_build_object('endpoint',test_endpoint));if (value->>'enabled')::boolean is distinct from true then raise exception 'Subscription not saved';end if;
 execute 'reset role';
 select s.id into sid from soundbar_private.sb_push_subscriptions s where s.endpoint=test_endpoint;
 insert into auth.users(id,email,raw_user_meta_data) values(c,c||'@example.invalid','{}');
 if (select count(*) from soundbar_private.sb_push_events where source_account=c)<>1 then raise exception 'Signup not queued exactly once';end if;
 events:=public.sb_webpush_server('claim');
 select x into job from jsonb_array_elements(events) x where x->>'id'=(select id::text from soundbar_private.sb_push_events where source_account=c);
 if job is null or not exists(select 1 from jsonb_array_elements(job->'subscriptions') s where s->>'id'=sid::text) then raise exception 'Admin recipient missing';end if;
 perform public.sb_webpush_server('record',jsonb_build_object('event',job->>'id','lease',job->>'lease','subscription',sid,'status',201));
 perform public.sb_webpush_server('finish',jsonb_build_object('event',job->>'id','lease',job->>'lease'));
 if not exists(select 1 from soundbar_private.sb_push_events where id=(job->>'id')::uuid and completed) then raise exception 'Delivery not completed';end if;
 if exists(select 1 from soundbar_private.sb_push_recipients((job->>'id')::uuid) where id=sid) then raise exception 'Delivered notification would repeat';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);execute 'set local role authenticated';
 perform public.sb_admin_notifications('unsubscribe',jsonb_build_object('endpoint',test_endpoint));
 if (public.sb_admin_notifications('config',jsonb_build_object('endpoint',test_endpoint))->>'enabled')::boolean then raise exception 'Unsubscribe failed';end if;
 execute 'reset role';
end$$;
rollback;
